SELECT id, user_id, sender_id, type, content, target_id, is_read, create_time
FROM tui_notification
WHERE id = #{id}

SELECT id, user_id, sender_id, type, content, target_id, is_read, create_time
FROM tui_notification
WHERE user_id = #{userId} AND id < #{cursor}
ORDER BY id DESC
LIMIT #{limit}
